code_example:
#include <vector>
#include <iostream>

// Generic class template
template <typename Container>
class ContainerWrapper {
public:
    Container data;
    void add(const typename Container::value_type& value) {
        data.push_back(value);
    }
    void print() const {
        for (const auto& item : data) {
            std::cout << item << ' ';
        }
        std::cout << '\n';
    }
};

// Specialization for std::vector<int>
template <>
class ContainerWrapper<std::vector<int>> {
public:
    std::vector<int> data;
    void add(int value) {
        data.insert(data.begin(), value); // custom behavior
    }
    void print() const {
        for (int item : data) {
            std::cout << item << ' ';
        }
        std::cout << '\n';
    }
};

int main() {
    ContainerWrapper<std::vector<std::string>> stringWrapper;
    stringWrapper.add("Hello");
    stringWrapper.add("World");
    stringWrapper.print();

    ContainerWrapper<std::vector<int>> intWrapper;
    intWrapper.add(42);
    intWrapper.add(7);
    intWrapper.print();

    // Using auto for type deduction
    auto x = 10; // compiler deduces int
    auto y = 3.14; // compiler deduces double
    std::cout << "x = " << x << ", y = " << y << '\n';
    return 0;
}
